/** URLs of every bundled art asset (generated by tools/prepare_game_assets.py). */
const files = import.meta.glob("./assets/**/*.webp", { eager: true, import: "default", query: "?url" }) as Record<string, string>

const byKey: Record<string, string> = {}
for (const [path, url] of Object.entries(files)) {
  byKey[path.replace("./assets/", "").replace(/\.webp$/, "")] = url
}

/** asset("sym/L1") -> bundled URL. Throws on a missing key so typos fail loudly in dev. */
export function asset(key: string): string {
  const url = byKey[key]
  if (!url) throw new Error(`missing asset: ${key}`)
  return url
}

export function assetsMatching(prefix: string): string[] {
  return Object.keys(byKey).filter((k) => k.startsWith(prefix)).sort().map((k) => byKey[k]!)
}

const TITLE_KEYS: Record<string, string> = {
  "BIG WIN": "title_big_win",
  "MEGA WIN": "title_mega_win",
  "TIDAL WAVE": "title_tidal_wave",
  "ABYSSAL WIN": "title_abyssal_win",
  "LEGENDARY CATCH": "title_legendary_catch",
  "MAX WIN": "title_max_win",
  "FEATURE COMPLETE": "title_feature_complete",
  "THE LEVIATHAN RISES": "title_leviathan_rises",
  RIPTIDE: "title_riptide",
  UNDERTOW: "title_undertow",
  MAELSTROM: "title_maelstrom",
  ABYSSAL: "title_abyssal_tier",
}

/** Painted title image for an overlay heading, or null to fall back to text. */
export function titleImage(text: string): string | null {
  const key = TITLE_KEYS[text.toUpperCase()]
  return key ? asset(`lettering/${key}`) : null
}

/** Preload images so first use does not pop in. */
export function preload(urls: string[]): void {
  for (const u of urls) {
    const img = new Image()
    img.decoding = "async"
    img.src = u
  }
}
